    JSONObject snapshot(JSONObject n)throws Exception{JSONObject base=new JSONObject();Iterator<String> keys=n.keys();while(keys.hasNext()){String key=keys.next();if(!key.equals("versions"))base.put(key,n.opt(key));}return new JSONObject(base.toString());}
    String snapshotText(JSONObject n){try{return snapshot(n).toString();}catch(Exception e){return "";}}
    void saveEditor() {
        handler.removeCallbacks(autosave);
        if(editing==null||title==null)return;
        JSONObject previous;String before;
        try{previous=snapshot(editing);before=previous.toString();}catch(Exception e){message("Impossible de créer la version précédente");return;}
        put(editing,"title",title.getText().toString()); put(editing,"body",body.getText().toString());put(editing,"tags",tags.getText().toString());
        JSONArray fs=editing.optJSONArray("fields");
        for(int i=0;i<fs.length();i++) { JSONObject f=fs.optJSONObject(i);EditText e=fields.get(f.optString("id"));if(e!=null){put(f,"value",e.getText().toString());if(f.optBoolean("required")&&e.getText().toString().trim().isEmpty())e.setError("À compléter");} }
        JSONArray blocks=editing.optJSONArray("blocks");if(blocks!=null)for(int i=0;i<blocks.length();i++){JSONObject block=blocks.optJSONObject(i);EditText e=blockEditors.get(block.optString("id"));if(e!=null)put(block,"text",e.getText().toString());else if(block.optString("type").equals("Question / réponse")){EditText q=blockEditors.get(block.optString("id")+".question"),a=blockEditors.get(block.optString("id")+".answer");if(q!=null&&a!=null)put(block,"text",q.getText().toString()+"\n---\n"+a.getText().toString());}}
        if(!before.equals(snapshotText(editing))) {
            JSONArray versions=editing.optJSONArray("versions");
            // Coalesce changes in one editing session minute to avoid a version per keystroke.
            if(versions.length()==0||System.currentTimeMillis()-versions.optJSONObject(versions.length()-1).optLong("snapshotAt")>60000) {put(previous,"snapshotAt",System.currentTimeMillis());versions.put(previous);}
            while(versions.length()>20)versions.remove(0);
            put(editing,"updated",System.currentTimeMillis());persist();
        }
    }
