    void moveField(JSONObject n,String id) {
        saveEditor();JSONArray old=n.optJSONArray("fields");List<JSONObject> ordered=new ArrayList<>();int index=-1;for(int j=0;j<old.length();j++){JSONObject f=old.optJSONObject(j);ordered.add(f);if(f.optString("id").equals(id))index=j;}if(index<=0)return;Collections.swap(ordered,index,index-1);JSONArray next=new JSONArray();for(JSONObject f:ordered)next.put(f);put(n,"fields",next);persist();editing=null;edit(n);
    }
    void preview() {
        saveEditor();android.text.SpannableStringBuilder rich=new android.text.SpannableStringBuilder();boolean code=false;
        for(String line:(editing==null?body.getText().toString():markdown(editing)).split("\\n",-1)) {
            if(line.startsWith("```")){code=!code;continue;}
            boolean heading=!code&&line.startsWith("#");boolean quote=!code&&line.startsWith(">");String text=line;
            if(heading)text=line.replaceFirst("^#+\\s*","");else if(quote)text=line.replaceFirst("^>\\s*","");else if(!code&&line.startsWith("- "))text="• "+line.substring(2);
            int start=rich.length();rich.append(text).append('\n');int end=rich.length();
            if(heading){rich.setSpan(new android.text.style.StyleSpan(android.graphics.Typeface.BOLD),start,end,33);rich.setSpan(new android.text.style.RelativeSizeSpan(1.3f),start,end,33);}
            if(quote)rich.setSpan(new android.text.style.StyleSpan(android.graphics.Typeface.ITALIC),start,end,33);
            if(code)rich.setSpan(new android.text.style.TypefaceSpan("monospace"),start,end,33);
        }
        TextView view=new TextView(this);view.setText(rich);view.setTextSize(17);view.setTextIsSelectable(true);view.setPadding(24,24,24,24);ScrollView scroll=new ScrollView(this);scroll.addView(view);new AlertDialog.Builder(this).setTitle(title.getText().toString()).setView(scroll).setPositiveButton("Fermer",null).show();
    }
