    void attach(Uri uri) {
        if(editing==null)return;saveEditor();JSONObject owner=editing;String replace=replacingFile;replacingFile="";String blockType=pendingBlockType;pendingBlockType="";editing=null;
        background("Copie du fichier…",()->{
            String name="Fichier";try(Cursor c=getContentResolver().query(uri,null,null,null,null)){if(c!=null&&c.moveToFirst()){int idx=c.getColumnIndex(OpenableColumns.DISPLAY_NAME);if(idx>=0)name=c.getString(idx);}}
            String id=UUID.randomUUID().toString();File dir=new File(getFilesDir(),"attachments");dir.mkdirs();File dest=new File(dir,id);
            try(InputStream in=getContentResolver().openInputStream(uri);FileOutputStream out=new FileOutputStream(dest)){if(in==null)throw new IOException("Fichier inaccessible");copy(in,out);}catch(Exception e){dest.delete();runOnUiThread(()->edit(owner));throw e;}
            String finalId=id;String fingerprint=hash(dest);File[] existing=new File(getFilesDir(),"attachments").listFiles();if(existing!=null)for(File candidate:existing){if(candidate.equals(dest)||candidate.length()!=dest.length())continue;if(hash(candidate).equals(fingerprint)){finalId=candidate.getName();dest.delete();break;}}
            JSONObject f=new JSONObject();put(f,"id",finalId);put(f,"name",name);put(f,"sha256",fingerprint);runOnUiThread(()->{if(!replace.isEmpty()){JSONArray files=owner.optJSONArray("files");for(int i=0;i<files.length();i++)if(files.optJSONObject(i).optString("id").equals(replace)){files.remove(i);break;}JSONArray blocks=owner.optJSONArray("blocks");if(blocks!=null)for(int i=0;i<blocks.length();i++)if(blocks.optJSONObject(i).optString("fileId").equals(replace))put(blocks.optJSONObject(i),"fileId",f.optString("id"));}addAttachmentRecord(owner,f,blockType);persist();edit(owner);});
        });
    }
